    for (const x of [-16.65, -15.35]) {
      addBox(elevator, [0.08, 0.08, 1.4], [x, 11.85, elevatorZ], materials.cage, false, false);
    }

    // Hopper: square upper bin with a four-sided tapered lower cone.
    addBox(elevator, [3.4, 0.55, 3.4], [-16, 14.25, elevatorZ], materials.yellow);
    addBox(elevator, [3.7, 0.18, 3.7], [-16, 14.58, elevatorZ], materials.darkSteel);

    const hopperCone = addCylinder(
      elevator,
      1.35,
      0.42,
