      materials.darkSteel,
      16
    );

    // Hopper rim.
    for (const x of [-17.7, -14.3]) {
      addBox(elevator, [0.18, 0.25, 3.7], [x, 14.6, elevatorZ], materials.darkSteel);
    }
    for (const z of [elevatorZ - 1.8, elevatorZ + 1.8]) {
      addBox(elevator, [3.5, 0.25, 0.18], [-16, 14.6, z], materials.darkSteel);
    }

    // Discharge chute.
    addBox(elevator, [1.3, 0.25, 2.1], [-16, 12.72, elevatorZ - 0.55], materials.darkSteel);

    // Elevator motor and gearbox.
    addBox(elevator, [1.6, 1.3, 1.6], [-16, 12.25, elevatorZ + 1.05], materials.darkSteel);
