    );
    hopperLabel.position.set(-16, 15.7, elevatorZ);
    scene.add(hopperLabel);

    // ---------------------------------------------------------------------
    // Gantry trolley and synchronized pressing head
    // ---------------------------------------------------------------------

    const trolley = new THREE.Group();
    trolley.position.set(trainX, 11, 0);
    scene.add(trolley);

    addBox(trolley, [2.25, 0.8, 2.2], [0, 0, 0], materials.darkSteel);
