    addBox(trolley, [0.16, 0.8, 0.16], [0.88, 0.25, 0], materials.green);

    const pressingHead = new THREE.Group();
    trolley.add(pressingHead);

    addBox(pressingHead, [1.8, 0.45, 1.45], [0, -0.45, 0], materials.darkSteel);

    const hydraulicOuter = addCylinder(
      pressingHead,
      0.22,
      0.22,
      2.8,
      [0, -2.15, 0],
      materials.steel,
      18
    );

    const hydraulicRod = addCylinder(
