      16
    );

    addBox(pressingHead, [2.25, 0.35, 2.25], [0, -7.5, 0], materials.yellow);
    addBox(pressingHead, [1.9, 0.12, 1.9], [0, -7.69, 0], materials.darkSteel);

    // ---------------------------------------------------------------------
    // Control cabinet and safety details
    // ---------------------------------------------------------------------

    const cabinet = new THREE.Group();
    cabinet.position.set(8, 0, 7);
    scene.add(cabinet);

    addBox(cabinet, [2.1, 3.2, 1.25], [0, 1.6, 0], materials.darkSteel);
    addBox(cabinet, [1.75, 1.25, 0.12], [0, 2.25, 0.68], materials.darkConcrete);

    const screen = addBox(
      cabinet,
      [1.45, 0.82, 0.08],
      [0, 2.3, 0.77],
      materials.glass,
      false,
      false
    );
    screen.rotation.x = -0.12;

    for (let i = 0; i < 4; i++) {
      addCylinder(
        cabinet,
        0.1,
        0.1,
        0.08,
        [-0.55 + i * 0.35, 1.45, 0.7],
        i === 0 ? materials.orange : materials.green,
        12,
        false
      );
    }

    // Small safety bollards.
    for (const [x, z] of [[-23, 8.6], [-10, 8.6], [-23, -8.6], [-10, -8.6]]) {
      addCylinder(scene, 0.12, 0.16, 1.1, [x, 0.55, z], materials.yellow, 12);
      addCylinder(scene, 0.13, 0.13, 0.2, [x, 0.8, z], materials.darkSteel, 12);
    }

    // ---------------------------------------------------------------------
    // Press status and animation
    // ---------------------------------------------------------------------

    const pressCycle = 9;
    const pressHomeZ = -7;

    const cars = [
      { number: 1, z: -12, offset: 0 },
      { number: 2, z: 0, offset: 9 },
      { number: 3, z: 12, offset: 18 }
    ];

    const pressState = cars.map(() => ({
      car: null,
      local: 0,
      trolleyZ: pressHomeZ,
      ramY: -2.8,
      active: false
    }));

    let elapsed = 0;
    let running = true;
    let speed = 1;

    const statusText = document.getElementById("statusText");
    const statusDot = document.getElementById("statusDot");
    const progressFill = document.getElementById("progressFill");
    const pauseButton = document.getElementById("pauseButton");
    const speedButton = document.getElementById("speedButton");
    const resetButton = document.getElementById("resetButton");

    pauseButton.addEventListener("click", () => {
      running = !running;
      pauseButton.textContent = running ? "Pause" : "Resume";
    });

    speedButton.addEventListener("click", () => {
      const speeds = [0.5, 1, 1.5, 2];
      const index = (speeds.indexOf(speed) + 1) % speeds.length;
      speed = speeds[index];
      speedButton.textContent = `Speed: ${speed.toFixed(1)}×`;
    });

    function updatePress(elapsed) {
      let activeCar = null;

      for (let i = 0; i < pressState.length; i++) {
        const state = pressState[i];
        const local = ((elapsed - state.car.offset) % pressCycle + pressCycle) % pressCycle;

        let trolleyZ = pressHomeZ;
        let ramY = -2.8;

        if (local >= 1.2 && local < 2.4) {
          const t = smooth01((local - 1.2) / 1.2);
          trolleyZ = lerp(pressHomeZ, state.car.z, t);
        } else if (local >= 2.4 && local < 3.8) {
          const t = smooth01((local - 2.4) / 1.4);
          ramY = lerp(-2.8, -7.5, t);
          trolleyZ = state.car.z;
        } else if (local >= 3.8 && local < 5) {
          const t = smooth01((local - 3.8) / 1.2);
          ramY = lerp(-7.5, -2.8, t);
          trolleyZ = state.car.z;
        } else if (local >= 5) {
          trolleyZ = pressHomeZ;
        }

        state.local = local;
        state.trolleyZ = trolleyZ;
        state.ramY = ramY;

        if (local >= 2.4 && local < 5 && !state.active) {
          state.active = true;
          activeCar = state.car;
        }
      }

      trolley.position.z = pressState[0].trolleyZ;
      pressingHead.position.y = pressState[0].ramY;

      let status = "PLANT CYCLE RUNNING";
      let color = "#65e3a5";

      if (activeCar) {
        status = `PRESSING CAR ${activeCar.number}`;
      } else if (elapsed % pressCycle < 1.2) {
        status = "GANTRY TROLLEY POSITIONING";
      } else if (elapsed % pressCycle < 2.4) {
        status = "LOADING REGOLITH INTO KILN CAR";
      } else if (elapsed % pressCycle < 3.8) {
        status = "APPLYING SINTERING PRESSURE";
      } else if (elapsed % pressCycle < 5) {
        status = "RELEASING SINTERED PART";
      } else {
        status = "RETURNING TO HOME POSITION";
      }

      statusText.textContent = status;
      statusDot.style.background = color;
      statusDot.style.boxShadow = `0 0 12px ${color}`;

      const cycleProgress = (elapsed % 27) / 27;
      progressFill.style.width = `${cycleProgress * 100}%`;
    }

    // ---------------------------------------------------------------------
    // Custom camera controls: orbit, pan, zoom, and reset
    // ---------------------------------------------------------------------

    const cameraTarget = defaultTarget.clone();
    const spherical = defaultSpherical.clone();

    function updateCamera() {
      spherical.phi = clamp(spherical.phi, 0.22, 1.46);
      spherical.radius = clamp(spherical.radius, 24, 115);
      spherical.makeSafe();

      camera.position.setFromSpherical(spherical).add(cameraTarget);
      camera.lookAt(cameraTarget);
      camera.updateMatrixWorld();
    }

    function resetCamera() {
      cameraTarget.copy(defaultTarget);
      spherical.copy(defaultSpherical);
      updateCamera();
    }

    resetButton.addEventListener("click", resetCamera);

    const canvas = renderer.domElement;
    const pointer = {
      active: false,
      x: 0,
      y: 0,
      button: 0
    };

    canvas.addEventListener("contextmenu", event => event.preventDefault());

    canvas.addEventListener("pointerdown", event => {
      if (event.button !== 0 && event.button !== 2) return;

      pointer.active = true;
      pointer.x = event.clientX;
      pointer.y = event.clientY;
      pointer.button = event.button;

      canvas.setPointerCapture(event.pointerId);
      canvas.classList.add("dragging");
    });

    canvas.addEventListener("pointermove", event => {
      if (!pointer.active) return;

      const dx = event.clientX - pointer.x;
      const dy = event.clientY - pointer.y;
      pointer.x = event.clientX;
      pointer.y = event.clientY;

      if (pointer.button === 2 || event.shiftKey) {
        const forward = new THREE.Vector3();
        camera.getWorldDirection(forward);

        const right = new THREE.Vector3()
          .crossVectors(forward, camera.up)
          .normalize();

        const up = new THREE.Vector3()
          .crossVectors(right, forward)
          .normalize();

        const panScale = spherical.radius * 0.0013;

        cameraTarget.addScaledVector(right, -dx * panScale);
        cameraTarget.addScaledVector(up, dy * panScale);
      } else {
        spherical.theta -= dx * 0.006;
        spherical.phi -= dy * 0.006;
      }

      updateCamera();
    });

    function endPointer(event) {
      pointer.active = false;
      canvas.classList.remove("dragging");

      if (event.pointerId !== undefined && canvas.hasPointerCapture(event.pointerId)) {
        canvas.releasePointerCapture(event.pointerId);
      }
    }

    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);

    canvas.addEventListener(
      "wheel",
      event => {
        event.preventDefault();
        spherical.radius *= Math.exp(event.deltaY * 0.001);
        updateCamera();
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", resetCamera);

    // ---------------------------------------------------------------------
    // Animation loop
    // ---------------------------------------------------------------------

    function animate() {
      requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.05);

      if (running) {
        elapsed += delta * speed;
      }

      // Elevator bucket motion.
      buckets.forEach((bucket, i) => {
        const angle = elapsed * 0.72 + i * bucketStep;
        bucket.position.set(
          -16 + Math.cos(angle) * 0.75,
          4 + Math.sin(angle) * 5.5,
          elevatorZ
        );
      });

      // Visible regolith falling from the hopper.
      flowParticles.forEach(particle => {
        const fall = (elapsed * 1.25 + particle.offset) % 1;
        particle.mesh.position.y = 12.95 - fall * 0.68;
        particle.mesh.position.x =
          particle.x + Math.sin(elapsed * 2.2 + particle.offset * 8) * 0.1;
        particle.mesh.position.z =
          particle.z + Math.cos(elapsed * 1.9 + particle.offset * 6) * 0.08;
      });

      // Small sintering dust around the active press point.
      const dust = new THREE.Group();
      scene.add(dust);

      if (activeCar) {
        dust.visible = true;

        for (let i = 0; i < 18; i++) {
          const angle = i * 2.399;
          const radius = 0.45 + (i % 5) * 0.25;
          const particle = addSphere(
            dust,
            0.055,
            [0, 0, 0],
            materials.regolithDark,
            7
          );

          particle.position.set(
            Math.cos(angle) * radius,
            0.08 + (i % 3) * 0.08,
            Math.sin(angle) * radius
          );
          particle.rotation.x = elapsed * 0.8 + i;
          particle.rotation.z = elapsed * 0.55 + i * 0.7;
        }
      } else {
        dust.visible = false;
      }

      // Subtle kiln-glow variation.
      kilnLightA.intensity = 54 + Math.sin(elapsed * 1.7) * 5;
      kilnLightB.intensity = 42 + Math.sin(elapsed * 1.3 + 1.2) * 4;

      updatePress(elapsed);
      renderer.render(scene, camera);
    }

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    updateCamera();
    updatePress(0);
    animate();

    requestAnimationFrame(() => {
      document.getElementById("loading").classList.add("hidden");
    });
  </script>
